void life_draw_stable (void)
{
for (int i = 1; i &lt; DIM - 2; i += 4)
for (int j = 1; j &lt; DIM - 2; j += 4) {
set_cell (i, j);
set_cell (i, j + 1);
set_cell (i + 1, j);
set_cell (i + 1, j + 1);
}
}
void life_draw_oscil (void)
{
for (int i = 2; i &lt; DIM - 4; i += 4)
for (int j = 2; j &lt; DIM - 4; j += 4) {
if ((j - 2) % 8) {
set_cell (i + 1, j);
set_cell (i + 1, j + 1);
set_cell (i + 1, j + 2);
} else {
set_cell (i, j + 1);
set_cell (i + 1, j + 1);
set_cell (i + 2, j + 1);
}
}
}
